<?php
if(!defined('ABSPATH'))exit;
function dgs_school_columns(){return array_merge(array('national_id','full_name','phone','guardian_phone','student_code','class_id'),array_keys(dgs_record_fields()));}
function dgs_school_xlsx($rows){
 require_once ABSPATH.'wp-admin/includes/file.php';
 require_once ABSPATH.'wp-admin/includes/class-pclzip.php';$dir=trailingslashit(get_temp_dir()).'dgs-xlsx-'.bin2hex(random_bytes(8));if(!wp_mkdir_p($dir.'/xl/worksheets')||!wp_mkdir_p($dir.'/xl/_rels')||!wp_mkdir_p($dir.'/_rels'))return dgs_edu_error('temp','پوشه موقت اکسل ساخته نشد.');$sheet='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';
 foreach($rows as $i=>$row){$sheet.='<row r="'.($i+1).'">';foreach(array_values($row) as $j=>$value)$sheet.='<c r="'.chr(65+$j).($i+1).'" t="inlineStr"><is><t xml:space="preserve">'.htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8').'</t></is></c>';$sheet.='</row>';}$sheet.='</sheetData></worksheet>';
 $files=array('[Content_Types].xml'=>'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml'=>'<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Students" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml'=>$sheet);$paths=array();foreach($files as $name=>$content){$path=$dir.'/'.$name;file_put_contents($path,$content);$paths[]=$path;}$target=wp_tempnam('dgs-roster.xlsx');$zip=new PclZip($target);$ok=$zip->create($paths,PCLZIP_OPT_REMOVE_PATH,$dir);$bytes=$ok?file_get_contents($target):false;foreach($paths as $path)@unlink($path);foreach(array('/xl/worksheets','/xl/_rels','/_rels','/xl','') as $path)@rmdir($dir.$path);@unlink($target);return $bytes===false?dgs_edu_error('xlsx','ساخت اکسل انجام نشد.'):$bytes;
}
function dgs_school_xlsx_rows($path){
 if(!function_exists('simplexml_load_string'))return dgs_edu_error('xml','افزونه SimpleXML روی هاست لازم است.');require_once ABSPATH.'wp-admin/includes/class-pclzip.php';$zip=new PclZip($path);$list=$zip->listContent();if(!is_array($list)||count($list)>2000)return dgs_edu_error('xlsx','فایل XLSX معتبر نیست.');$total=0;$names=array();foreach($list as $entry){$total+=(int)$entry['size'];$names[$entry['filename']]=true;}if($total>20*1024*1024||!isset($names['xl/worksheets/sheet1.xml']))return dgs_edu_error('xlsx','فایل باید از الگو ساخته شود و حجم بازشده حداکثر ۲۰ مگابایت باشد.');
 $read=function($name)use($zip){$parts=$zip->extract(PCLZIP_OPT_BY_NAME,$name,PCLZIP_OPT_EXTRACT_AS_STRING);if(!is_array($parts)||!isset($parts[0]['content']))return false;$text=$parts[0]['content'];if(stripos($text,'<!DOCTYPE')!==false||stripos($text,'<!ENTITY')!==false)return false;return @simplexml_load_string($text,'SimpleXMLElement',LIBXML_NONET);};$strings=array();if(isset($names['xl/sharedStrings.xml'])){$shared=$read('xl/sharedStrings.xml');if(!$shared)return dgs_edu_error('xlsx','متن‌های اکسل معتبر نیستند.');foreach($shared->xpath('//*[local-name()="si"]') as $si){$s='';foreach($si->xpath('.//*[local-name()="t"]') as $txt)$s.=(string)$txt;$strings[]=$s;}}
 $xml=$read('xl/worksheets/sheet1.xml');if(!$xml)return dgs_edu_error('xlsx','ساختار صفحه اکسل معتبر نیست.');$rows=array();foreach($xml->xpath('//*[local-name()="sheetData"]/*[local-name()="row"]') as $row){$out=array_fill(0,count(dgs_school_columns()),'');foreach($row->xpath('./*[local-name()="c"]') as $cell){if($cell->xpath('./*[local-name()="f"]'))return dgs_edu_error('formula','سلول فرمول‌دار مجاز نیست.');$ref=(string)$cell['r'];if(!preg_match('/^([A-Z])\d+$/D',$ref,$m))continue;$col=ord($m[1])-65;if($col>=count(dgs_school_columns()))continue;$type=(string)$cell['t'];if($type==='inlineStr'){$value='';foreach($cell->xpath('.//*[local-name()="t"]') as $text)$value.=(string)$text;}else{$v=$cell->xpath('./*[local-name()="v"]');$value=$v?(string)$v[0]:'';if($type==='s')$value=$strings[(int)$value]??'';}$out[$col]=trim($value);}if(implode('',$out)==='')continue;$rows[]=$out;if(count($rows)>101)return dgs_edu_error('rows','حداکثر ۱۰۰ دانش‌آموز در هر بار وارد کنید.');}
 $legacy=$rows&&array_slice($rows[0],0,6)===array('national_id','full_name','phone','guardian_phone','student_code','class_id')&&implode('',array_slice($rows[0],6))==='';if(!$rows||(!$legacy&&$rows[0]!==dgs_school_columns()))return dgs_edu_error('headers','عنوان ستون‌های فایل الگو نباید تغییر کند.');array_shift($rows);return $rows;
}
function dgs_school_import($file,$d){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','اجازه ورود اکسل ندارید.');$year=is_string($d['year']??null)?dgs_edu_year($d['year']):'';if(!$year||!is_array($file)||($file['error']??1)!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name']??'')||($file['size']??0)>2*1024*1024||strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION))!=='xlsx')return dgs_edu_error('file','فایل الگوی XLSX تا ۲ مگابایت و سال معتبر لازم است.');$rows=dgs_school_xlsx_rows($file['tmp_name']);if(is_wp_error($rows))return $rows;return dgs_school_import_rows($rows,$year);
}
function dgs_school_import_rows($rows,$year){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','اجازه ورود اکسل ندارید.');if(!dgs_edu_year($year)||!is_array($rows)||!$rows||count($rows)>100)return dgs_edu_error('rows','فهرست ۱ تا ۱۰۰ نفری در سال معتبر لازم است.');global $wpdb;$e=dgs_edu_tables();$clean=array();$seen=array();foreach($rows as $i=>$row){if(!is_array($row)||!in_array(count($row),array(6,count(dgs_school_columns())),true))return dgs_edu_error('row','ستون‌های ردیف معتبر نیستند.');foreach($row as $value)if(!is_scalar($value))return dgs_edu_error('row','مقدار سلول معتبر نیست.');$record=dgs_record_validate(count($row)>6?array_combine(array_keys(dgs_record_fields()),array_slice($row,6)):array());if(is_wp_error($record))return dgs_edu_error('record','ردیف '.dgs_fa_digits($i+2).': '.$record->get_error_message());list($national,$name,$phone,$guardian,$code,$class)=$row;$national=dgs_edu_digits((string)$national);$name=sanitize_text_field((string)$name);$phone=dgs_normalize_phone((string)$phone);$guardian=(string)$guardian;$code=sanitize_text_field((string)$code);$class=dgs_edu_digits((string)$class);$uid=username_exists($national);
 if(!dgs_edu_national_id($national)||isset($seen[$national])||!$name||dgs_edu_length($name)>100||!$phone||($guardian!==''&&!dgs_normalize_phone($guardian))||dgs_edu_length($code)>30||($class!==''&&(!ctype_digit($class)||!(int)$class))||($uid&&!dgs_edu_role($uid,'dgs_student')))return dgs_edu_error('row','اطلاعات ردیف '.dgs_fa_digits($i+2).' معتبر نیست یا کد ملی تکراری است.');$seen[$national]=true;if($class!==''){$c=dgs_edu_class($class);if(!$c||$c->school_year!==$year)return dgs_edu_error('class','کلاس ردیف '.dgs_fa_digits($i+2).' فعالِ همین سال نیست.');if($uid){$old=$wpdb->get_var($wpdb->prepare("SELECT class_id FROM {$e['enrollments']} WHERE student_id=%d AND school_year=%s",$uid,$year));if($old&&(int)$old!==(int)$class)return dgs_edu_error('class','دانش‌آموز ردیف '.dgs_fa_digits($i+2).' کلاس دیگری دارد؛ انتقال را از فرم انتساب انجام دهید.');}}
 $clean[]=array('national'=>$national,'name'=>$name,'phone'=>$phone,'guardian'=>$guardian===''?'':dgs_normalize_phone($guardian),'code'=>$code,'class'=>(int)$class,'uid'=>$uid?:0,'record'=>$record);}
 $wpdb->query('START TRANSACTION');$created=array();$touched=array();$error=false;foreach($clean as $row){$uid=$row['uid'];if($uid)$touched[]=$uid;if(!$uid){$uid=wp_insert_user(array('user_login'=>$row['national'],'user_pass'=>$row['national'],'display_name'=>$row['name'],'nickname'=>$row['name'],'role'=>'dgs_student','user_email'=>''));if(is_wp_error($uid)){$error=true;break;}$created[]=get_userdata($uid);foreach(array('_dgs_contact_phone'=>$row['phone'],'_dgs_guardian_phone'=>$row['guardian'],'_dgs_student_code'=>$row['code'],'_dgs_created_by'=>get_current_user_id()) as $key=>$value)if(!add_user_meta($uid,$key,$value,true)){$error=true;break;}if($error)break;$record=$row['record'];$record['revision']=1;$record['registration_year']=$year;$record['updated_by']=get_current_user_id();$record['updated_at']=current_time('mysql');if(!add_user_meta($uid,'_dgs_record',$record,true)){$error=true;break;}}
 if($row['record']['registration']!==''&&!metadata_exists('user',$uid,'_dgs_registration_'.$year))if(!add_user_meta($uid,'_dgs_registration_'.$year,$row['record']['registration'],true)){$error=true;break;}
 if($row['class']&&!$wpdb->get_var($wpdb->prepare("SELECT id FROM {$e['enrollments']} WHERE student_id=%d AND school_year=%s",$uid,$year))&&!$wpdb->insert($e['enrollments'],array('student_id'=>$uid,'class_id'=>$row['class'],'school_year'=>$year,'created_at'=>current_time('mysql')))){$error=true;break;}}
 if($error){$wpdb->query('ROLLBACK');foreach($touched as $uid)wp_cache_delete($uid,'user_meta');foreach($created as $u)if($u){clean_user_cache($u);wp_cache_delete($u->ID,'user_meta');}return dgs_edu_error('write','ورود کامل نشد؛ هیچ ردیفی ثبت نشد.');}$wpdb->query('COMMIT');dgs_edu_audit('students_import',count($clean));return dgs_fa_digits(count($clean)).' ردیف بررسی شد؛ '.dgs_fa_digits(count($created)).' حساب جدید ساخته شد. حساب‌های موجود بازنویسی نشدند.';
}
add_action('admin_post_dgs_school_export',function(){
 if(!current_user_can('dgs_manage_education'))wp_die('اجازه خروجی ندارید.','',array('response'=>403));check_admin_referer('dgs_school_export');$year=dgs_edu_year(dgs_att_get('year'));if(!$year)wp_die('سال معتبر نیست.');$rows=array(dgs_school_columns());if(!empty($_GET['template']))$rows[]=array_fill(0,count(dgs_school_columns()),'');else{$filters=array('grade'=>dgs_att_get('sd_grade'),'field'=>dgs_att_get('sd_field'),'class'=>dgs_att_get('sd_class'));$users=dgs_school_roster_query($year,$filters,2001,0);if(count($users)>2000)wp_die('خروجی بیش از ۲۰۰۰ نفر است؛ فیلتر پایه یا کلاس را محدود کنید.');foreach($users as $u){$m=get_user_meta($u->ID,'_dgs_record',true);$m=is_array($m)?$m:array();$extras=array();foreach(dgs_record_fields() as $k=>$label)$extras[]=$k==='registration'?dgs_record_registration($u->ID,$year,$m):($m[$k]??'');$rows[]=array_merge(array($u->user_login,$u->display_name,get_user_meta($u->ID,'_dgs_contact_phone',true),get_user_meta($u->ID,'_dgs_guardian_phone',true),get_user_meta($u->ID,'_dgs_student_code',true),$u->class_id?:''),$extras);}}
 $bytes=dgs_school_xlsx($rows);if(is_wp_error($bytes))wp_die(esc_html($bytes->get_error_message()));nocache_headers();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="daneshgaran-students-'.$year.'.xlsx"');header('Content-Length: '.strlen($bytes));while(ob_get_level())ob_end_clean();echo $bytes;exit;
});
